    /** 唯一冻结格式：{@code {"schema_version":1,"images":[{"media_id":"...","caption":"..."}]}}。 */
    private static String imagesRef(UUID... ids) {
        StringBuilder sb = new StringBuilder("{\"schema_version\":1,\"images\":[");
        for (int i = 0; i < ids.length; i++) {
            if (i > 0) {
                sb.append(',');
            }
            sb.append("{\"media_id\":\"").append(ids[i]).append("\",\"caption\":\"c").append(i)
                    .append("\"}");
        }
        return sb.append("]}").toString();
    }

    /** 旧兼容形态 (a)：{@code public_media_ids[]}——必须拒绝。 */
    private static String legacyPublicMediaIds(UUID id) {
        return "{\"schema_version\":1,\"public_media_ids\":[\"" + id + "\"]}";
    }

    /** 旧兼容形态 (b)：{@code photos[].public=true}——必须拒绝。 */
    private static String legacyPhotos(UUID id) {
        return "{\"schema_version\":1,\"photos\":[{\"media_id\":\"" + id + "\",\"public\":true}]}";
    }

    /** 旧兼容形态 (c)：T05 {@code photo_versions[].public=true}——必须拒绝。 */
    private static String legacyPhotoVersionsColumn(UUID id) {
        return "[{\"media_id\":\"" + id + "\",\"public\":true}]";
    }

    /** 驼峰变体：{@code mediaId}——冻结格式用下划线，必须拒绝。 */
    private static String camelCaseImages(UUID id) {
        return "{\"schema_version\":1,\"images\":[{\"mediaId\":\"" + id + "\"}]}";
    }

