        GimbalScenario s = gimbalScenario(gimbal, memberId); // credential_version=1, current=task
        MediaObject media = mediaService.load(s.mediaId());
        assertNotNull(media);

        PrincipalContext matching = PrincipalContext.forGimbal(
                AuthenticatedPrincipal.gimbal(gimbal.id(), 1L, "s"), "req-ok");
        assertTrue(accessPolicy.canAccess(matching, media),
                "credential_version 相符且 current 任务 → 放行");

        // 直接构造不匹配凭据代次，绕过 A 的 revalidator，验证策略自身防线
        PrincipalContext mismatched = PrincipalContext.forGimbal(
                AuthenticatedPrincipal.gimbal(gimbal.id(), 2L, "s"), "req-bad");
        assertFalse(accessPolicy.canAccess(mismatched, media),
                "credential_version 不符 → 策略必须拒绝");
